test "test_exec_rpt_end_of_stream_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = ExecRptEndOfStream{
        .pbu = "aaaaaaaa",
        .set_id = 123456,
        .end_report_index = 123456789,
